var n=`1085-sisig`;var o=`world-1085`;var s=`PH`;var t=`southeast-asia`;var a=4;var r=77;var l={en:`Sisig`,ua:`Сісіг`};var d={en:`Sisig is a dish from Philippines prepared with pork shoulder, garlic, yellow onion, light soy sauce. This is a home-scale version with measured ingredients in the individual steps where they are used. Home sisig uses pork shoulder rather than customary chopped pig head and ears; eggs are fully cooked.`,ua:`Сісіг, страва кухні країни Філіппіни, яку готують із таких продуктів: свиняча лопатка, часник, жовта цибуля, світлий соєвий соус. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Домашній сісіг із лопатки замість голови та вух; яйця повністю приготовані.`};var u=[{en:`Cook the listed ingredients in simmering water for about 50 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 50 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:50,i:[[`pork-shoulder`,600,`g`],[`water`,900,`ml`],[`garlic`,4,`clove`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`canola-oil`,35,`ml`],[`yellow-onion`,200,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`light-soy-sauce`,35,`ml`],[`lime-juice`,50,`ml`],[`serrano-pepper`,2,`pcs`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 7 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 7 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:7,i:[[`chicken-egg`,2,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,30,`g`]]}];var g={slug:n,id:o,country:`PH`,region:t,servings:4,minutes:77,title:l,text:d,steps:u};export{s as country,g as default,o as id,r as minutes,t as region,a as servings,n as slug,u as steps,d as text,l as title};